</div>
<script>
(function(){
  const root=document.getElementById("sine-surface-app");
  if(!root || root.dataset.ready==="true")return;
  root.dataset.ready="true";
  const canvas=root.querySelector("#s-canvas");
  const stage=root.querySelector("#s-stage");
  const state={yaw:-.56,pitch:.89,zoom:1,wire:false,color:"#42adf5"};
  const initial={yaw:-.56,pitch:.89,zoom:1};
  const N=80,verts=[],norms=[],tri=[],lines=[];
  const range=Math.PI*2;
  for(let j=0;j<=N;j++){
    const y=-Math.PI+range*j/N;
    for(let i=0;i<=N;i++){
      const x=-Math.PI+range*i/N;
      verts.push(x,y,Math.sin(x)*Math.cos(y));
      const nx=-Math.cos(x)*Math.cos(y),ny=Math.sin(x)*Math.sin(y);
      const length=Math.hypot(nx,ny,1);
      norms.push(nx/length,ny/length,1/length);
    }
  }
  for(let j=0;j<N;j++)for(let i=0;i<N;i++){
    const a=j*(N+1)+i,b=a+1,c=a+N+1,d=c+1;
    tri.push(a,b,c,b,d,c);
  }
  for(let j=0;j<=N;j++)for(let i=0;i<N;i++){let a=j*(N+1)+i;if(i<N)lines.push(a,a+1);if(j<N)lines.push(a,a+N+1);}
  function rgb(hex){return [parseInt(hex.slice(1,3),16)/255,parseInt(hex.slice(3,5),16)/255,parseInt(hex.slice(5,7),16)/255]}
  let gl=null,program=null,render2D=null;
  try{gl=canvas.getContext("webgl",{antialias:true,alpha:false,depth:true,preserveDrawingBuffer:false});}catch(e){}
  const vs=`
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    uniform float uYaw,uPitch,uScale,uAspect;
    varying vec3 vNormal;
    varying float vHeight;
    void main(){
      float c=cos(uYaw),s=sin(uYaw),p=cos(uPitch),t=sin(uPitch);
      vec3 q=vec3(c*aPosition.x-s*aPosition.y,s*aPosition.x+c*aPosition.y,aPosition.z);
      vec3 r=vec3(q.x,p*q.y-t*q.z,t*q.y+p*q.z);
      vec3 n=vec3(c*aNormal.x-s*aNormal.y,s*aNormal.x+c*aNormal.y,aNormal.z);
      vNormal=vec3(n.x,p*n.y-t*n.z,t*n.y+p*n.z);
      vHeight=aPosition.z;
      gl_Position=vec4(r.x*uScale/uAspect,r.z*uScale,-r.y*.105,1.0);
    }`;
  const fs=`
    precision mediump float;
    uniform vec3 uColor;
    uniform float uWire;
    varying vec3 vNormal;
    varying float vHeight;
    void main(){
      vec3 n=normalize(vNormal);
      vec3 light=normalize(vec3(-0.4,-0.5,0.85));
      float diff=max(dot(n,light),0.0);
      float intensity=0.47+0.53*diff;
      vec3 shaded=uColor*intensity+vec3(0.075)*max(vHeight,0.0);
      vec3 wire=mix(uColor,vec3(1.0),0.32);
      gl_FragColor=vec4(uWire>0.5?wire:shaded,1.0);
    }`;
  function compileShader(type,source){
    let s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);
    if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));
    return s;
  }
  let pb,nb,tb,lb,loc={};
  try{
    if(!gl)throw Error("No WebGL");
    program=gl.createProgram();
    gl.attachShader(program,compileShader(gl.VERTEX_SHADER,vs));
    gl.attachShader(program,compileShader(gl.FRAGMENT_SHADER,fs));
    gl.linkProgram(program);
    if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error("WebGL link failed");
    gl.useProgram(program);
    for(const a of ["aPosition","aNormal"])loc[a]=gl.getAttribLocation(program,a);
    for(const u of ["uYaw","uPitch","uScale","uAspect","uColor","uWire"])loc[u]=gl.getUniformLocation(program,u);
    pb=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,pb);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(verts),gl.STATIC_DRAW);
    nb=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,nb);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(norms),gl.STATIC_DRAW);
    tb=gl.createBuffer();gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,tb);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(tri),gl.STATIC_DRAW);
    lb=gl.createBuffer();gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,lb);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(lines),gl.STATIC_DRAW);
    gl.enable(gl.DEPTH_TEST);gl.depthFunc(gl.LEQUAL);
    root.querySelector("#s-renderer").textContent="● WebGL";
  }catch(e){
    gl=null;program=null;
    root.querySelector("#s-renderer").textContent="● Canvas 2D";
  }
  function projected(x,y,z,sc,w,h){
    const cy=Math.cos(state.yaw),sy=Math.sin(state.yaw),cp=Math.cos(state.pitch),sp=Math.sin(state.pitch);
    const qx=cy*x-sy*y,qy=sy*x+cy*y;
    const rz=sp*qy+cp*z,ry=cp*qy-sp*z;
    return [w*.5+qx*sc*h*.5,h*.5-rz*sc*h*.5,ry];
  }
  function canvasFallback(w,h){
    const c=canvas.getContext("2d");if(!c)return;
    c.fillStyle="#0a1424";c.fillRect(0,0,w,h);
    const n=40,step=Math.PI*2/n,scale=.36*state.zoom;
    const grid=[];
    for(let j=0;j<=n;j++){
      let row=[];
      for(let i=0;i<=n;i++){
        const x=-Math.PI+step*i,y=-Math.PI+step*j,z=Math.sin(x)*Math.cos(y);
        row.push(projected(x,y,z,scale,w,h));
      }
      grid.push(row);
    }
    const co=rgb(state.color);
    if(!state.wire){
      const cells=[];
      for(let j=0;j<n;j++)for(let i=0;i<n;i++){
        const a=grid[j][i],b=grid[j][i+1],d=grid[j+1][i+1],e=grid[j+1][i];
        const x=-Math.PI+step*(i+.5),y=-Math.PI+step*(j+.5);
        const normal=[-Math.cos(x)*Math.cos(y),Math.sin(x)*Math.sin(y),1];
        const cy=Math.cos(state.yaw),sy=Math.sin(state.yaw),cp=Math.cos(state.pitch),sp=Math.sin(state.pitch);
        const nx=cy*normal[0]-sy*normal[1],ny=sy*normal[0]+cy*normal[1];
        const n2=[nx,cp*ny-sp*normal[2],sp*ny+cp*normal[2]];
        const diff=Math.max(0,(-.4*n2[0]-.5*n2[1]+.85*n2[2])/(Math.hypot(...n2)*Math.hypot(-.4,-.5,.85)));
        const brightness=.47+.53*diff;
        cells.push({pts:[a,b,d,e],dep:(a[2]+b[2]+d[2]+e[2])/4,br:brightness});
      }
      cells.sort((a,b)=>a.dep-b.dep);
      for(const p of cells){
        c.beginPath();c.moveTo(p.pts[0][0],p.pts[0][1]);
        for(let k=1;k<4;k++)c.lineTo(p.pts[k][0],p.pts[k][1]);c.closePath();
        c.fillStyle=`rgb(${Math.round(co[0]*255*p.br)},${Math.round(co[1]*255*p.br)},${Math.round(co[2]*255*p.br)})`;
        c.fill();
      }
    }else{
      c.strokeStyle=`rgba(${Math.round(co[0]*255)},${Math.round(co[1]*255)},${Math.round(co[2]*255)},.9)`;
      c.lineWidth=.8;
      for(let j=0;j<=n;j++){c.beginPath();for(let i=0;i<=n;i++){const p=grid[j][i];if(!i)c.moveTo(p[0],p[1]);else c.lineTo(p[0],p[1]);}c.stroke();}
      for(let i=0;i<=n;i++){c.beginPath();for(let j=0;j<=n;j++){const p=grid[j][i];if(!j)c.moveTo(p[0],p[1]);else c.lineTo(p[0],p[1]);}c.stroke();}
    }
  }
  function render(){
    const rect=stage.getBoundingClientRect();
    const dpr=Math.min(window.devicePixelRatio||1,2);
    const w=Math.max(1,Math.round(rect.width*dpr)),h=Math.max(1,Math.round(rect.height*dpr));
    if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}
    if(!gl||!program){canvasFallback(w,h);return;}
    gl.viewport(0,0,w,h);gl.clearColor(.039,.078,.141,1);
    gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);
    gl.useProgram(program);
    gl.uniform1f(loc.uYaw,state.yaw);gl.uniform1f(loc.uPitch,state.pitch);
    gl.uniform1f(loc.uScale,.36*state.zoom);gl.uniform1f(loc.uAspect,w/h);
    gl.uniform3fv(loc.uColor,new Float32Array(rgb(state.color)));
    gl.uniform1f(loc.uWire,state.wire?1:0);
    gl.bindBuffer(gl.ARRAY_BUFFER,pb);gl.enableVertexAttribArray(loc.aPosition);gl.vertexAttribPointer(loc.aPosition,3,gl.FLOAT,false,0,0);
    gl.bindBuffer(gl.ARRAY_BUFFER,nb);gl.enableVertexAttribArray(loc.aNormal);gl.vertexAttribPointer(loc.aNormal,3,gl.FLOAT,false,0,0);
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,state.wire?lb:tb);
    gl.drawElements(state.wire?gl.LINES:gl.TRIANGLES,state.wire?lines.length:tri.length,gl.UNSIGNED_SHORT,0);
  }
  let raf=0;
  function requestRender(){if(raf)return;raf=requestAnimationFrame(()=>{raf=0;render()})}
  root.querySelector("#s-solid").addEventListener("click",()=>setMode(false));
  root.querySelector("#s-wire").addEventListener("click",()=>setMode(true));
  function setMode(wire){
    state.wire=wire;
    root.querySelector("#s-solid").classList.toggle("active",!wire);
    root.querySelector("#s-wire").classList.toggle("active",wire);
    root.querySelector("#s-mode-status").textContent=wire?"线框渲染":"实体渲染";
    requestRender();
  }
  function setColor(color,fromSwatch){
    state.color=color;root.querySelector("#s-custom").value=color;
    root.querySelectorAll(".s-swatch").forEach(b=>b.classList.toggle("selected",fromSwatch&&b.dataset.color===color));
    requestRender();
  }
  root.querySelectorAll(".s-swatch").forEach(b=>b.addEventListener("click",()=>setColor(b.dataset.color,true)));
  root.querySelector("#s-custom").addEventListener("input",e=>setColor(e.target.value,false));
  function updateZoom(v){state.zoom=Number(v)/100;root.querySelector("#s-zoom").value=String(v);root.querySelector("#s-zoom-label").textContent=Math.round(v)+"%";requestRender();}
  root.querySelector("#s-zoom").addEventListener("input",e=>updateZoom(e.target.value));
  root.querySelector("#s-reset").addEventListener("click",()=>{state.yaw=initial.yaw;state.pitch=initial.pitch;updateZoom(100);});
  let dragging=false,lastX=0,lastY=0;
  canvas.addEventListener("pointerdown",e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId);});
  canvas.addEventListener("pointermove",e=>{
    if(!dragging)return;
    const dx=e.clientX-lastX,dy=e.clientY-lastY;
    lastX=e.clientX;lastY=e.clientY;
    state.yaw+=dx*.009;
    state.pitch=Math.max(.08,Math.min(1.55,state.pitch+dy*.009));
    requestRender();
  });
  canvas.addEventListener("pointerup",()=>{dragging=false});
  canvas.addEventListener("pointercancel",()=>{dragging=false});
  canvas.addEventListener("lostpointercapture",()=>{dragging=false});
  stage.addEventListener("wheel",e=>{
    e.preventDefault();
    updateZoom(Math.max(60,Math.min(170,Number(root.querySelector("#s-zoom").value)+(e.deltaY<0?5:-5))));
  },{passive:false});
  if(typeof ResizeObserver!=="undefined")new ResizeObserver(requestRender).observe(stage);
  else window.addEventListener("resize",requestRender);
  requestRender();
})();
</script>

